/** The routes about a member's account. */
export function memberRoutes(store) {
  return [
    {
      method: 'GET',
      path: '/members/:id/summary',
      handle: ({ params }) => {
        const member = store.getMember(params.id);
        const balanceCents = outstandingBalance(store, member.id);
